def solve(inputs: dict) -> float:
    # General solver for iterated 32-bit xorshift of the form:
    # X ^= (X<<13); X ^= (X>>7); X ^= (X<<15), repeated n times.
    # Accepts possible input keys for start value and repetitions.
    x = None
    n = None
    for k in ("x", "X", "start", "value", "seed"):
        if k in inputs:
            x = int(inputs[k])
            break
    for k in ("n", "steps", "iters", "iterations", "repetitions"):
        if k in inputs:
            n = int(inputs[k])
            break
    if x is None or n is None:
        raise ValueError('Unsupported input format')
    x &= 0xFFFFFFFF
    for _ in range(n):
        x ^= (x << 13) & 0xFFFFFFFF
        x ^= (x >> 7) & 0xFFFFFFFF
        x ^= (x << 15) & 0xFFFFFFFF
        x &= 0xFFFFFFFF
    return float(x)

